CREATE TABLE IF NOT EXISTS admin_users (id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL DEFAULT 'Administrator',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,image_url TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,description TEXT NOT NULL DEFAULT '',price REAL NOT NULL CHECK(price>=0),sale_price REAL,category_id TEXT REFERENCES categories(id) ON DELETE SET NULL,stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),sku TEXT UNIQUE,featured INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,details TEXT NOT NULL DEFAULT '{}',images TEXT NOT NULL DEFAULT '[]',variants TEXT NOT NULL DEFAULT '[]',sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,address TEXT,city TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY,order_number TEXT UNIQUE NOT NULL,customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL,customer_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,address TEXT NOT NULL,city TEXT,notes TEXT,payment_method TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'pending',payment_transaction_id TEXT,payment_sender_number TEXT,status TEXT NOT NULL DEFAULT 'pending',subtotal REAL NOT NULL,delivery_charge REAL NOT NULL DEFAULT 0,total REAL NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id TEXT REFERENCES products(id) ON DELETE SET NULL,product_name TEXT NOT NULL,sku TEXT,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price REAL NOT NULL,variant TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,method TEXT NOT NULL,transaction_id TEXT,sender_number TEXT,amount REAL NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT,email TEXT,message TEXT NOT NULL,interest TEXT,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY,customer_name TEXT NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),review_text TEXT NOT NULL,image_url TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',image_url TEXT,price REAL,button_text TEXT,button_action TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS banners (id TEXT PRIMARY KEY,heading TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',image_url TEXT,button_text TEXT,button_action TEXT,active INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS landing_sections (id TEXT PRIMARY KEY,section_key TEXT UNIQUE NOT NULL,title TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',content TEXT NOT NULL DEFAULT '{}',enabled INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS social_links (id TEXT PRIMARY KEY,platform TEXT UNIQUE NOT NULL,url TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS site_settings (key TEXT PRIMARY KEY,value TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_active ON products(active); CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id); CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status); CREATE INDEX IF NOT EXISTS idx_leads_status ON leads(status);
